import { getJson, postJson } from '../../api/http';

// A project as the API exposes it — it carries its client's NAME (the cross-entity join done on the
// server) so the list shows the client without a second lookup. The query key ['projects'] is the
// shared handle: the list reads it, the create form invalidates it.
export type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
};
export type NewProject = { name: string; clientId: number };

export const projectsKey = ['projects'] as const;

export const listProjects = (): Promise<Project[]> => getJson<Project[]>('/api/projects');

export const createProject = (body: NewProject): Promise<Project> =>
  postJson<Project>('/api/projects', body);

// Archive a project — tucks it away server-side (keeps the row, sets its archived flag) and returns
// the updated project. Callers invalidate ['projects'] on success so the list refetches and the row
// drops off, unless the archived ones are being shown.
export const archiveProject = (id: number): Promise<Project> =>
  postJson<Project>('/api/projects/archive', { id });

// The client options the form's select needs: shared with the clients feature by the ['clients']
// KEY (not an import), so adding a client refreshes this select too.
export type ClientOption = { id: number; name: string };
export const clientsKey = ['clients'] as const;
export const listClientOptions = (): Promise<ClientOption[]> =>
  getJson<ClientOption[]>('/api/clients');

import { useQuery } from '@tanstack/react-query';
import { projectsKey, listProjects, type Project } from './api';
import { ProjectRow } from '../../slots/defs/projectRow';
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { useSearchParam, asFlag } from '../../url/useSearchParam';

// The projects list. Reads server data under ['projects'] (never copied into state); the create form
// shares the key, so a successful create refreshes this list with no import between them. Each row
// shows the client's NAME, which the server joins onto the project.
//
// Archived projects are tucked away: they drop off the list unless the `showArchived` URL key is on.
// The toggle control (its own *.slot.tsx) owns that key; this list reads the same key and filters,
// so they stay in step through the shared search param with nothing passed between them.
export function ProjectsList() {
  const [showArchived] = useSearchParam('showArchived', asFlag);
  const { data: projects } = useQuery({ queryKey: projectsKey, queryFn: listProjects });

  if (!projects) {
    return null;
  }

  const visible = projects.filter((project: Project) => showArchived || !project.archived);

  return (
    <>
      <ProjectsToolbar.Slot />
      {visible.length === 0 ? (
        <p data-testid="projects-empty">No projects yet.</p>
      ) : (
        <ProjectsTable projects={visible} />
      )}
    </>
  );
}

function ProjectsTable({ projects }: { projects: Project[] }) {
  return (
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {projects.map((project: Project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <ProjectRow.Slot projectId={project.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

